// ===== Keystone shared library (generated from ops/lib; do not edit here) =====
const __KS = (() => {
  const defs = {
  'opsmanager': function (module, exports, require) {
'use strict';
// Keystone Ops Manager: morning/evening summaries, instant notices for key moments,
// and YES/NO approvals (SMS reply once Twilio has a number; email links until then).

const { escapeHtml: e } = require('./log');

function settingsMap(records) {
  const S = {};
  for (const r of records || []) { const f = r.fields || r; if (f.Setting) S[f.Setting] = String(f.Value || '').trim(); }
  return S;
}

// Which channel(s) to use for Bilal. Business escalations use the same SMS switch.
function channels(S) {
  const smsReady = !!(S.twilio_from && S.alert_sms_to);
  const mode = (S.ops_channel || 'auto').toLowerCase();
  if (mode === 'email' || !smsReady) return { sms: false, email: true, smsReady };
  if (mode === 'both') return { sms: true, email: true, smsReady };
  return { sms: true, email: false, smsReady };
}

function approvalCode() { return String(Math.floor(1000 + Math.random() * 9000)); }

// "YES 4821", "y 4821", "no4821", "4821 yes" -> {decision, code}
function parseReply(text) {
  const t = String(text || '').trim().toLowerCase();
  const code = (t.match(/\b(\d{4})\b/) || [])[1] || null;
  let decision = null;
  if (/\b(yes|y|approve|ok|okay|go)\b/.test(t)) decision = 'yes';
  if (/\b(no|n|reject|stop|cancel)\b/.test(t)) decision = decision ? null : 'no';
  return { decision, code };
}

const KIND_LABEL = {
  urgent_call: 'URGENT CALL', complaint: 'COMPLAINT', message: 'Message', quote_approval: 'Quote to approve',
  invoice_review: 'Invoice to review', failure: 'Workflow failure', info: 'Update', booking: 'New booking',
};

function smsText(n, code) {
  const head = `${KIND_LABEL[n.kind] || 'Keystone'}${n.clientName ? ' - ' + n.clientName : ''}: `;
  const tail = code ? ` Reply YES ${code} or NO ${code}.` : '';
  return (head + (n.text || n.title || '')).slice(0, 320 - tail.length) + tail;
}

function emailHtml(n, links) {
  const btn = (href, label, colour) => `<a href="${e(href)}" style="display:inline-block;background:${colour};color:#fff;padding:12px 18px;border-radius:6px;text-decoration:none;margin-right:8px">${label}</a>`;
  return `<div style="font-family:Arial,sans-serif;max-width:620px">
<h2 style="margin:0 0 8px;color:${n.kind === 'urgent_call' || n.kind === 'complaint' ? '#b91c1c' : '#1F3A5F'}">${e(KIND_LABEL[n.kind] || 'Keystone')}${n.clientName ? ' - ' + e(n.clientName) : ''}</h2>
<p style="font-size:15px;white-space:pre-wrap">${e(n.text || '')}</p>
${links ? `<p>${btn(links.yes, 'YES', '#059669')}${btn(links.no, 'NO', '#6b7280')}</p><p style="font-size:12px;color:#6b7280">Approval code ${e(links.code)}. Once SMS is set up you can also reply to the text with YES ${e(links.code)} or NO ${e(links.code)}.</p>` : ''}
<p style="font-size:12px;color:#6b7280">Keystone Ops Manager</p></div>`;
}

// ---------- summaries ----------
function inWindow(ts, from, to) { const t = Date.parse(ts); return t >= from.getTime() && t < to.getTime(); }
const f = (r) => (r && r.fields ? r.fields : r || {});
const sel = (v) => (v && v.name) || v || '';

function summarise({ logs = [], calls = [], quotes = [], reviews = [], approvals = [], clients = [] }, from, to) {
  const L = logs.map(f).filter((r) => inWindow(r['Timestamp'], from, to));
  const C = calls.map(f).filter((r) => inWindow(r['Timestamp'], from, to));
  const Q = quotes.map(f).filter((r) => inWindow(r['Created'], from, to));
  const count = (arr, pred) => arr.filter(pred).length;
  const nameOf = (id) => (clients.map(f).find((c) => c['Client ID'] === id) || {})['Client name'] || id || 'Keystone';
  const failures = L.filter((r) => sel(r['Outcome']) === 'Escalated' && sel(r['Service']) === 'monitor');
  return {
    invoicesDrafted: count(L, (r) => String(r['Event']).startsWith('invoice_') && sel(r['Outcome']) === 'Draft created'),
    invoicesToReview: count(L, (r) => String(r['Event']).startsWith('invoice_') && sel(r['Outcome']) === 'Sent to review'),
    calls: C.length,
    bookings: count(C, (r) => ['Booking', 'Reschedule'].includes(sel(r['Category']))),
    urgent: C.filter((r) => sel(r['Category']) === 'Urgent').map((r) => `${nameOf(r['Client ID'])}: ${String(r['Summary'] || '').slice(0, 80)}`),
    complaints: C.filter((r) => sel(r['Category']) === 'Complaint').map((r) => `${nameOf(r['Client ID'])}: ${String(r['Summary'] || '').slice(0, 80)}`),
    quotes: Q.length,
    quotesValue: Math.round(Q.reduce((s, r) => s + (Number(r['Total']) || 0), 0)),
    failures: failures.map((r) => `${r['Reference'] || 'workflow'} (${nameOf(r['Client ID'])})`),
    openReviews: reviews.map(f).filter((r) => sel(r['Status']) === 'Open').length,
    pendingApprovals: approvals.map(f).filter((r) => sel(r['Status']) === 'Pending').map((r) => ({ code: r['Code'], summary: r['Summary'] })),
    activeClients: clients.map(f).filter((c) => sel(c['Status']) === 'Active').length,
  };
}

function summaryText(kind, s, dateLabel) {
  const lines = [];
  lines.push(kind === 'morning' ? `Good morning. Overnight and yesterday evening (${dateLabel}):` : `End of day (${dateLabel}):`);
  lines.push(`- ${s.activeClients} active clients`);
  lines.push(`- Invoices drafted: ${s.invoicesDrafted}${s.invoicesToReview ? ` (${s.invoicesToReview} need review)` : ''}`);
  lines.push(`- Calls: ${s.calls}, bookings: ${s.bookings}`);
  lines.push(`- Quotes: ${s.quotes}${s.quotesValue ? ` (£${s.quotesValue.toLocaleString('en-GB')})` : ''}`);
  if (s.urgent.length) lines.push(`- URGENT calls: ${s.urgent.join('; ')}`);
  if (s.complaints.length) lines.push(`- Complaints: ${s.complaints.join('; ')}`);
  if (s.failures.length) lines.push(`- Failures: ${s.failures.join('; ')}`);
  lines.push(`- Open review items: ${s.openReviews}`);
  if (s.pendingApprovals.length) lines.push(`- Waiting for your YES/NO: ${s.pendingApprovals.map((a) => `#${a.code} ${String(a.summary).slice(0, 60)}`).join('; ')}`);
  if (!s.urgent.length && !s.complaints.length && !s.failures.length && !s.openReviews && !s.pendingApprovals.length) lines.push('Nothing needs you right now.');
  return lines.join('\n');
}

function summarySms(kind, s) {
  const needs = s.urgent.length + s.complaints.length + s.failures.length + s.openReviews + s.pendingApprovals.length;
  return `Keystone ${kind === 'morning' ? 'AM' : 'PM'}: ${s.invoicesDrafted} invoices, ${s.calls} calls/${s.bookings} bookings, ${s.quotes} quotes. ${needs ? needs + ' need you' + (s.pendingApprovals.length ? ' (approvals: ' + s.pendingApprovals.map((a) => a.code).join(', ') + ')' : '') : 'All clear.'}`.slice(0, 320);
}

module.exports = { settingsMap, channels, approvalCode, parseReply, smsText, emailHtml, summarise, summaryText, summarySms, KIND_LABEL };

  },
  'log': function (module, exports, require) {
'use strict';
// One shape for every Agent Log row. Every agent or workflow decision goes through this.

const OPS_EMAIL = 'khan.bilalbk408@gmail.com'; // Bilal (Resend account owner, so test-sender mail is delivered)

// Conservative admin-time estimates (minutes a person would have spent). Used for value reports.
const MINUTES_SAVED = {
  invoice_draft_created: 12,
  invoice_agent_fixed: 20,
  invoice_queued: 2,
  call_handled: 5,
  booking_made: 8,
  reschedule: 6,
  urgent_escalated: 5,
  complaint_logged: 8,
  message_taken: 4,
  quote_drafted: 25,
  issue_auto_fixed: 20,
  weekly_report: 45,
  monthly_report: 90,
};

function logRecord({ clientId, service, event, decision, reasoning, outcome, confidence, reference, workflow, executionId, details, now }) {
  const minutes = MINUTES_SAVED[event] || 0;
  const summary = `[${clientId || 'keystone'}] ${service}: ${event}${outcome ? ' -> ' + outcome : ''}`.slice(0, 250);
  return {
    'Summary': summary,
    'Client ID': clientId || '',
    'Service': service,
    'Event': event,
    'Decision': decision || '',
    'Reasoning': reasoning || '',
    'Outcome': outcome || 'Success',
    'Confidence': typeof confidence === 'number' ? Math.max(0, Math.min(1, confidence)) : null,
    'Reference': reference || '',
    'Minutes saved': ['Success', 'Draft created', 'Auto-fixed', 'Escalated'].includes(outcome || 'Success') ? minutes : 0,
    'Timestamp': (now || new Date()).toISOString(),
    'Workflow': workflow || '',
    'Execution ID': executionId ? String(executionId) : '',
    'Details JSON': details ? JSON.stringify(details).slice(0, 90000) : '',
  };
}

function escapeHtml(s) {
  return String(s === undefined || s === null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Airtable filterByFormula string literal escaping.
function formulaString(s) {
  return "'" + String(s || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
}

module.exports = { OPS_EMAIL, MINUTES_SAVED, logRecord, escapeHtml, formulaString };

  },
  'requests': function (module, exports, require) {
'use strict';
// Request builders for the HTTP Request nodes. Each returns {url, method, body, tenantId?}
// and goes on an item as $json.req. Credentials come from n8n, never from here.

const { formulaString } = require('./log');

const AIRTABLE_API = 'https://api.airtable.com/v0';
// Change once a domain is verified in Resend (BLOCKERS.md). resend.dev only delivers to the Resend account owner.
const EMAIL_FROM = 'Keystone <onboarding@resend.dev>';

function qs(pairs) {
  // n8n's Code sandbox has no URLSearchParams, so encode by hand.
  return pairs.map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
}

function airtableList(baseId, tableId, { formula, fields, maxRecords = 100, sort } = {}) {
  const q = [];
  if (formula) q.push(['filterByFormula', formula]);
  if (maxRecords) q.push(['maxRecords', String(maxRecords)]);
  (fields || []).forEach((f) => q.push(['fields[]', f]));
  (sort || []).forEach((s, i) => { q.push([`sort[${i}][field]`, s.field]); q.push([`sort[${i}][direction]`, s.direction || 'asc']); });
  return { method: 'GET', url: `${AIRTABLE_API}/${baseId}/${tableId}?${qs(q)}` };
}

function airtableCreate(baseId, tableId, fieldsList) {
  return { method: 'POST', url: `${AIRTABLE_API}/${baseId}/${tableId}`, body: { records: fieldsList.slice(0, 10).map((f) => ({ fields: clean(f) })), typecast: true } };
}

function airtableUpdate(baseId, tableId, updates) {
  return { method: 'PATCH', url: `${AIRTABLE_API}/${baseId}/${tableId}`, body: { records: updates.slice(0, 10).map((u) => ({ id: u.id, fields: clean(u.fields) })), typecast: true } };
}

// Create-or-update by a unique text field (e.g. Period), so re-runs don't duplicate rows.
function airtableUpsert(baseId, tableId, mergeOn, fieldsList) {
  return { method: 'PATCH', url: `${AIRTABLE_API}/${baseId}/${tableId}`, body: { performUpsert: { fieldsToMergeOn: mergeOn }, records: fieldsList.slice(0, 10).map((f) => ({ fields: clean(f) })), typecast: true } };
}

function clean(f) {
  const o = {};
  for (const [k, v] of Object.entries(f || {})) if (v !== undefined && v !== null && !(typeof v === 'number' && !isFinite(v))) o[k] = v;
  return o;
}

function byClientFormula(clientId, extra) {
  const base = `{Client ID} = ${formulaString(clientId)}`;
  return extra ? `AND(${base}, ${extra})` : base;
}

function email({ to, subject, html, text, replyTo, from }) {
  const list = (Array.isArray(to) ? to : [to]).filter(Boolean);
  return { method: 'POST', url: 'https://api.resend.com/emails', body: { from: from || EMAIL_FROM, to: list, subject: String(subject).slice(0, 200), html, text, ...(replyTo ? { reply_to: replyTo } : {}) } };
}

function xero(client, method, pathAndQuery, body) {
  return { method, url: `https://api.xero.com/api.xro/2.0/${pathAndQuery}`, body, tenantId: client.invoice.xeroTenantId };
}

// Real Xero calls only for live clients with a real tenant ID. Demo rows use the simulated path.
function useRealXero(client) {
  return !!client.invoice.xeroTenantId && !/^DEMO-/.test(client.invoice.xeroTenantId);
}

function gcal(calendarId, method, path, body) {
  return { method, url: `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(calendarId || 'primary')}/${path}`, body };
}

// Writes fan out to one shared tail (Airtable write / email / SMS) in every workflow.
const write = {
  airtable: (req) => ({ kind: 'airtable', req }),
  email: (req) => ({ kind: 'email', req }),
  sms: (from, to, message) => ({ kind: 'sms', sms: { from, to, message: String(message).slice(0, 600) } }),
  // Calls one of Keystone's own n8n webhooks (e.g. start another agent).
  webhook: (url, body, method = 'POST') => ({ kind: 'webhook', req: { url, method, body } }),
};

function ok(res) { return res && res.statusCode >= 200 && res.statusCode < 300; }

module.exports = { qs, write, AIRTABLE_API, EMAIL_FROM, airtableList, airtableCreate, airtableUpdate, airtableUpsert, byClientFormula, email, xero, useRealXero, gcal, ok, clean };

  },
  'registry': function (module, exports, require) {
'use strict';
// Client Registry: turns a "My Clients" Airtable row into one config object,
// and decides whether a given service may run for that client.
// Rule: every workflow calls gate() first and exits cleanly if it isn't ok.

// Resend's test sender only delivers to the Resend account owner, so demo mail goes here.
const TEST_INBOX = 'khan.bilalbk408@gmail.com';

const SERVICE_TOGGLES = {
  invoicing: 'Invoicing on',
  phone: 'Phone on',
  quotes: 'Quotes on',
  reporting: 'Reporting on',
  monitoring: 'Monitoring on',
};

// Jurisdictions where the phone agent must NOT be deployed (proactive AI disclosure required).
const BLOCKED_PHONE_JURISDICTIONS = ['Republic of Ireland / EU'];

function parseJson(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'object') return value;
  try { return JSON.parse(value); } catch (e) { return { __invalid: true, raw: String(value) }; }
}

function splitList(value) {
  if (!value) return [];
  return String(value).split(/[,;\n]/).map((s) => s.trim()).filter(Boolean);
}

// Accepts an Airtable record ({id, fields}) or a flattened n8n Airtable item.
function normalizeClient(record) {
  const f = record && record.fields ? record.fields : record || {};
  const services = parseJson(f['Services'], []);
  const hours = parseJson(f['Opening hours'], {});
  const pricing = parseJson(f['Pricing rules'], null);
  return {
    recordId: record.id || f.id || null,
    clientId: (f['Client ID'] || '').trim(),
    clientName: f['Client name'] || '',
    status: (f['Status'] && f['Status'].name) || f['Status'] || 'Onboarding',
    isDemo: !!f['Is demo/test'],
    contactName: f['Contact name'] || '',
    contactEmail: f['Contact email'] || '',
    contactPhone: f['Contact phone'] || '',
    industry: f['Industry'] || '',
    halalPassed: !!f['Halal screen passed'],
    jurisdiction: (f['Jurisdiction'] && f['Jurisdiction'].name) || f['Jurisdiction'] || '',
    aiDisclosurePassed: !!f['AI disclosure check passed'],
    toggles: {
      invoicing: !!f['Invoicing on'],
      phone: !!f['Phone on'],
      quotes: !!f['Quotes on'],
      reporting: !!f['Reporting on'],
      monitoring: !!f['Monitoring on'],
    },
    businessEmail: f['Business email'] || f['Contact email'] || '',
    timezone: f['Timezone'] || 'Europe/London',
    invoice: {
      brandLogoUrl: f['Brand logo URL'] || '',
      brandColour: f['Brand colour'] || '#1F3A5F',
      paymentOptions: f['Payment options'] || '',
      sendWindowStart: f['Send window start'] || '',
      sendWindowEnd: f['Send window end'] || '',
      milestoneInvoicingEnabled: !!f['Milestone invoicing enabled'],
      invoiceLineAmountType: (f['Invoice line amount type'] && f['Invoice line amount type'].name) || f['Invoice line amount type'] || 'Inclusive',
      vatRatePct: f['VAT rate %'] === undefined || f['VAT rate %'] === null ? 20 : Number(f['VAT rate %']),
      accountCode: f['Xero account code'] || '200',
      paymentTermsDays: f['Payment terms days'] === undefined || f['Payment terms days'] === null ? 14 : Number(f['Payment terms days']),
      xeroCredentialName: f['Xero credential name'] || '',
      xeroTenantId: f['Xero organisation ID'] || '',
      jobSource: (f['Job source'] && f['Job source'].name) || f['Job source'] || 'Airtable Jobs table',
    },
    phone: {
      businessNumber: normalizePhone(f['Business phone number']),
      receptionNumber: normalizePhone(f['Reception forwarding number']),
      calendarId: f['Calendar ID'] || '',
      services: Array.isArray(services) ? services : [],
      openingHours: hours && !hours.__invalid ? hours : {},
      greeting: f['Greeting'] || '',
      tone: f['Tone / brand voice'] || 'Warm, professional and concise.',
      urgentKeywords: splitList(f['Urgent keywords']),
      escalationSms: normalizePhone(f['Escalation SMS number'] || f['Reception forwarding number']),
    },
    quotes: {
      pricingRules: pricing,
      pricesIncludeVat: !!f['Prices include VAT'],
      validDays: Number(f['Quote valid days']) || 30,
      minMarginPct: f['Minimum margin %'] === undefined || f['Minimum margin %'] === null ? 30 : Number(f['Minimum margin %']),
      approverEmail: f['Quote approver email'] || f['Business email'] || f['Contact email'] || '',
    },
    reporting: { recipients: splitList(f['Report recipients']) },
    dashboardToken: f['Dashboard token'] || '',
    monthlyFee: f['Monthly fee'] || 0,
    prospectIds: f['Prospect'] || [],
    _invalidJson: [
      services && services.__invalid ? 'Services' : null,
      hours && hours.__invalid ? 'Opening hours' : null,
      pricing && pricing.__invalid ? 'Pricing rules' : null,
    ].filter(Boolean),
  };
}

function normalizePhone(p) {
  if (!p) return '';
  let s = String(p).replace(/[^\d+]/g, '');
  if (s.startsWith('00')) s = '+' + s.slice(2);
  if (s.startsWith('0')) s = '+44' + s.slice(1);
  if (!s.startsWith('+') && s.length >= 10) s = '+' + s;
  return s;
}

// The gate. Returns {ok:true} or {ok:false, reason}. Never throws.
function gate(client, service) {
  if (!client || !client.clientId) return { ok: false, reason: 'client_not_found' };
  if (client.status !== 'Active') return { ok: false, reason: `status_${String(client.status).toLowerCase()}` };
  if (!client.halalPassed) return { ok: false, reason: 'halal_screen_not_passed' };
  if (service && SERVICE_TOGGLES[service] && !client.toggles[service]) return { ok: false, reason: `${service}_toggle_off` };
  if (service === 'phone') {
    if (!client.aiDisclosurePassed) return { ok: false, reason: 'ai_disclosure_check_not_passed' };
    if (BLOCKED_PHONE_JURISDICTIONS.includes(client.jurisdiction)) return { ok: false, reason: 'jurisdiction_requires_ai_disclosure' };
  }
  if (client._invalidJson && client._invalidJson.length) {
    const relevant = { phone: ['Services', 'Opening hours'], quotes: ['Pricing rules'] }[service] || [];
    const bad = client._invalidJson.filter((x) => relevant.includes(x));
    if (bad.length) return { ok: false, reason: `invalid_json_${bad.join('_').replace(/\s/g, '').toLowerCase()}` };
  }
  return { ok: true };
}

// Pick the one client row for a lookup; refuses ambiguous matches (isolation).
function resolveClient(records, { clientId, phoneNumber } = {}) {
  const clients = (records || []).map(normalizeClient);
  let matches = [];
  if (clientId) matches = clients.filter((c) => c.clientId === String(clientId).trim());
  else if (phoneNumber) {
    const p = normalizePhone(phoneNumber);
    matches = clients.filter((c) => c.phone.businessNumber && c.phone.businessNumber === p);
  }
  if (matches.length === 0) return { client: null, error: 'client_not_found' };
  if (matches.length > 1) return { client: null, error: 'ambiguous_client_match' };
  return { client: matches[0], error: null };
}

// Demo/test safety: outbound email to anyone other than Keystone goes to the test inbox.
function safeRecipients(client, emails) {
  const list = (Array.isArray(emails) ? emails : [emails]).filter(Boolean);
  if (!client || client.isDemo) return list.length ? [TEST_INBOX] : [];
  return list;
}

function safeSmsNumber(client, number, testNumber) {
  if (!client || client.isDemo) return testNumber || null;
  return number;
}

// Registry-wide integrity checks: duplicate keys would break isolation.
function validateRegistry(records) {
  const clients = (records || []).map(normalizeClient);
  const problems = [];
  const dup = (key, label) => {
    const seen = {};
    for (const c of clients) {
      const v = key(c);
      if (!v) continue;
      if (seen[v]) problems.push(`Duplicate ${label} "${v}" on ${seen[v]} and ${c.clientName}`);
      else seen[v] = c.clientName;
    }
  };
  dup((c) => c.clientId, 'Client ID');
  dup((c) => c.phone.businessNumber, 'Business phone number');
  dup((c) => c.invoice.xeroTenantId, 'Xero organisation ID');
  dup((c) => c.dashboardToken, 'Dashboard token');
  for (const c of clients) if (!c.clientId) problems.push(`Client "${c.clientName || '(unnamed)'}" has no Client ID`);
  return problems;
}

module.exports = { TEST_INBOX, SERVICE_TOGGLES, BLOCKED_PHONE_JURISDICTIONS, parseJson, splitList, normalizeClient, normalizePhone, gate, resolveClient, safeRecipients, safeSmsNumber, validateRegistry };

  },
  'onboarding': function (module, exports, require) {
'use strict';
// Onboarding checklist: decides whether a registry row is safe to set Active,
// and which services can be switched on.

const { BLOCKED_PHONE_JURISDICTIONS } = require('./registry');
const { halalScreen } = require('./audit');

function item(id, label, done, detail) { return { id, label, done: !!done, detail: detail || '' }; }

function checklist(client) {
  const c = client;
  const screen = halalScreen(c.industry, c.clientName);
  const items = [
    item('client_id', 'Client ID set', !!c.clientId),
    item('contact', 'Contact name and email', c.contactName && c.contactEmail),
    item('halal', 'Halal screen passed', c.halalPassed && screen.pass, screen.pass ? (screen.needsManualCheck ? `Manual check advised: ${screen.checks.join(', ')}` : '') : `Industry text hits: ${screen.hits.join(', ')}`),
    item('jurisdiction', 'Jurisdiction recorded', !!c.jurisdiction),
    item('business_email', 'Business notification email', !!c.businessEmail),
  ];
  const svc = {};
  if (c.toggles.invoicing) {
    svc.invoicing = [
      item('xero_tenant', 'Xero organisation ID', !!c.invoice.xeroTenantId),
      item('send_window', 'Send window set (HH:MM)', /^\d{1,2}:\d{2}$/.test(c.invoice.sendWindowStart) && /^\d{1,2}:\d{2}$/.test(c.invoice.sendWindowEnd)),
      item('vat', 'Invoice line amount type', ['Inclusive', 'Exclusive', 'NoTax'].includes(c.invoice.invoiceLineAmountType)),
      item('job_source', 'Job source chosen', !!c.invoice.jobSource),
    ];
  }
  if (c.toggles.phone) {
    svc.phone = [
      item('ai_disclosure', 'AI-disclosure jurisdiction check passed', c.aiDisclosurePassed && !BLOCKED_PHONE_JURISDICTIONS.includes(c.jurisdiction), BLOCKED_PHONE_JURISDICTIONS.includes(c.jurisdiction) ? 'Jurisdiction requires proactive AI disclosure: phone agent may not be deployed' : ''),
